func omlxServer(modelID string, maxContext, maxTokens int) *httptest.Server {
	return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/v1/models/status" {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]interface{}{
			"models": []map[string]interface{}{
				{
					"id":                 modelID,
					"max_context_window": maxContext,
					"max_tokens":         maxTokens,
				},
			},
		})
	}))
}

// openrouterServer returns an httptest server that serves /models with
// model metadata including context_length and max_completion_tokens.
func openrouterServer(models map[string]struct{ context, maxCompletion int }) *httptest.Server {
	return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/models" {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		data := make([]map[string]interface{}, 0, len(models))
		for id, limits := range models {
			data = append(data, map[string]interface{}{
				"id":              id,
				"context_length": limits.context,
				"top_provider": map[string]interface{}{
					"max_completion_tokens": limits.maxCompletion,
				},
			})
		}
		_ = json.NewEncoder(w).Encode(map[string]interface{}{"data": data})
	}))
}

// TestLookupModelLimits_LMStudio_ValidResponse tests LM Studio's limit discovery.
func TestLookupModelLimits_LMStudio_ValidResponse(t *testing.T) {
	srv := lmStudioServer(4096, 8192)
	defer srv.Close()

	// Test with a model that has loaded_context_length set.
	limits := lmstudio.LookupModelLimits(context.Background(), srv.URL+"/v1", "test-model")
	require.NotZero(t, limits)
